#include <iostream>
#include <fstream>
#include <string>
#include <queue>
#include <mutex>
#include <thread>
#include <chrono>
#include <filesystem>
#include <functional>
#include <atomic>
#include <algorithm>
#include <sstream>
#include <cstdint>

namespace fs = std::filesystem;

struct Message {
    std::string topic;
    std::string payload;
    int retry_count;
    std::chrono::steady_clock::time_point next_retry;
};

class RateLimiter {
    std::chrono::steady_clock::time_point last_request_;
    std::chrono::milliseconds interval_;
    std::mutex mtx_;
public:
    RateLimiter(int requests_per_sec) 
        : interval_(1000 / std::max(requests_per_sec, 1)) {}

    void wait() {
        std::lock_guard<std::mutex> lock(mtx_);
        auto now = std::chrono::steady_clock::now();
        auto elapsed = now - last_request_;
        if (elapsed < interval_) {
            std::this_thread::sleep_for(interval_ - elapsed);
        }
        last_request_ = std::chrono::steady_clock::now();
    }
};

class PathValidator {
public:
    static std::string sanitize_component(const std::string& component) {
        std::string result;
        for (char c : component) {
            if (c == '/' || c == '\\' || c == '\0') continue;
            result += c;
        }
        return result;
    }

    static bool is_within_base(const fs::path& base, const fs::path& target) {
        auto canonical_base = fs::weakly_canonical(base);
        auto canonical_target = fs::weakly_canonical(target);
        auto [mismatch_base, mismatch_target] = std::mismatch(
            canonical_base.begin(), canonical_base.end(),
            canonical_target.begin(), canonical_target.end());
        return mismatch_base == canonical_base.end();
    }
};

class MessageConsumer {
    std::queue<Message> queue_;
    std::queue<Message> retry_queue_;
    std::mutex queue_mtx_;
    RateLimiter limiter_;
    std::atomic<bool> running_;
    fs::path output_base_;
    int max_retries_;

    std::string resolve_output_path(const Message& msg) {
        std::string sanitized_topic = PathValidator::sanitize_component(msg.topic);

        // Parse payload for optional subdirectory hint
        std::string subdir = "default";
        std::string content = msg.payload;

        auto sep_pos = msg.payload.find("|||");
        if (sep_pos != std::string::npos) {
            subdir = msg.payload.substr(0, sep_pos);
            content = msg.payload.substr(sep_pos + 3);
        }

        // Normalize the subdir: only allow alphanumeric and underscore
        std::string normalized_subdir;
        for (size_t i = 0; i < subdir.size(); i++) {
            char c = subdir[i];
            if (std::isalnum(static_cast<unsigned char>(c)) || c == '_' || c == '-') {
                normalized_subdir += c;
            }
        }
        if (normalized_subdir.empty()) normalized_subdir = "default";

        fs::path output_path = output_base_ / sanitized_topic / normalized_subdir / "message.dat";
        return output_path.string();
    }

    bool write_message(const Message& msg) {
        limiter_.wait();

        std::string path_str = resolve_output_path(msg);
        fs::path output_path(path_str);

        // Security check: verify path is within base directory
        if (!PathValidator::is_within_base(output_base_, output_path)) {
            std::cerr << "Security: path traversal blocked for topic: " << msg.topic << std::endl;
            return false;
        }

        fs::create_directories(output_path.parent_path());

        std::ofstream out(output_path, std::ios::app);
        if (!out.is_open()) return false;

        auto sep_pos = msg.payload.find("|||");
        std::string content = (sep_pos != std::string::npos) 
            ? msg.payload.substr(sep_pos + 3) : msg.payload;

        out << content << "\n";
        return out.good();
    }

    void schedule_retry(Message msg) {
        if (msg.retry_count >= max_retries_) {
            std::cerr << "Max retries exceeded for topic: " << msg.topic << std::endl;
            return;
        }
        msg.retry_count++;
        // Clamp shift amount to avoid undefined behavior / integer overflow
        // and cap the resulting backoff to a sane maximum.
        int shift = std::min(msg.retry_count, 20);
        std::int64_t backoff_ms = static_cast<std::int64_t>(100) * (static_cast<std::int64_t>(1) << shift);
        const std::int64_t max_backoff_ms = 60000; // 60 seconds
        if (backoff_ms > max_backoff_ms) backoff_ms = max_backoff_ms;
        msg.next_retry = std::chrono::steady_clock::now() + std::chrono::milliseconds(backoff_ms);
        std::lock_guard<std::mutex> lock(queue_mtx_);
        retry_queue_.push(msg);
    }

public:
    MessageConsumer(const std::string& output_dir, int rate_limit = 10, int max_retries = 3)
        : limiter_(rate_limit), running_(true), 
          output_base_(fs::weakly_canonical(output_dir)), max_retries_(max_retries) {
        fs::create_directories(output_base_);
    }

    void enqueue(const std::string& topic, const std::string& payload) {
        std::lock_guard<std::mutex> lock(queue_mtx_);
        queue_.push({topic, payload, 0, {}});
    }

    void process_one() {
        Message msg;
        {
            std::lock_guard<std::mutex> lock(queue_mtx_);
            // Check retry queue first
            if (!retry_queue_.empty()) {
                auto& front = retry_queue_.front();
                if (std::chrono::steady_clock::now() >= front.next_retry) {
                    msg = front;
                    retry_queue_.pop();
                } else if (!queue_.empty()) {
                    msg = queue_.front();
                    queue_.pop();
                } else return;
            } else if (!queue_.empty()) {
                msg = queue_.front();
                queue_.pop();
            } else return;
        }

        if (!write_message(msg)) {
            schedule_retry(msg);
        }
    }

    void run() {
        while (running_) {
            process_one();
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    }

    void stop() { running_ = false; }
};

int main() {
    MessageConsumer consumer("/var/spool/msgqueue/output", 50, 5);

    // Simulated message ingestion
    consumer.enqueue("orders", "subdir_a|||Order #1234 processed");
    consumer.enqueue("alerts", "critical|||System overload detected");

    std::thread worker([&consumer]() { consumer.run(); });
    std::this_thread::sleep_for(std::chrono::seconds(2));
    consumer.stop();
    worker.join();

    return 0;
}
